import { useCallback, useEffect, useRef, useState } from 'react';
import { Game } from './game/engine';
import { Input } from './game/input';
import { audio } from './game/audio';
import type { DiffKey, EndStats, HudState } from './game/entities';
import { Menu } from './components/Menu';
import { Hud } from './components/Hud';
import { GameOver, PauseMenu } from './components/Overlays';
import { TouchControls } from './components/TouchControls';

type Screen = 'menu' | 'play' | 'pause' | 'over';

const STYLE = `
@keyframes r42-blink { 50% { opacity: .15 } }
.r42-blink { animation: r42-blink 1s steps(1) infinite }
@keyframes r42-pop { 0% { transform: scale(.6); opacity: 0 } 12% { transform: scale(1.08); opacity: 1 } 22% { transform: scale(1) } 85% { opacity: 1 } 100% { opacity: 0 } }
.r42-pop { animation: r42-pop 2.6s ease-out both }
.r42-title { background: linear-gradient(180deg, #fff6b0 0%, #ffd23c 45%, #ff7a1e 100%); -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(3px 3px 0 #8c1c28) drop-shadow(0 0 18px rgba(255,140,40,.45)); }
`;

export default function App() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameRef = useRef<Game | null>(null);
  const [input, setInput] = useState<Input | null>(null);
  const [screen, setScreen] = useState<Screen>('menu');
  const [hud, setHud] = useState<HudState | null>(null);
  const [end, setEnd] = useState<EndStats | null>(null);
  const [diff, setDiff] = useState<DiffKey>('normal');
  const [muted, setMuted] = useState(false);
  const [hi, setHi] = useState(0);

  useEffect(() => {
    const inp = new Input();
    inp.attach();
    setInput(inp);
    const g = new Game(canvasRef.current!, inp, {
      onHud: setHud,
      onEnd: s => { setEnd(s); setHi(s.hi); setScreen('over'); },
    });
    gameRef.current = g;
    setHi(g.hi);
    const wrap = wrapRef.current!;
    const fit = () => { const r = wrap.getBoundingClientRect(); g.resize(r.width, r.height); };
    const ro = new ResizeObserver(fit);
    ro.observe(wrap);
    fit();
    g.run();
    return () => {
      ro.disconnect();
      g.destroy();
      inp.detach();
      audio.dispose();
      gameRef.current = null;
    };
  }, []);

  const play = useCallback(() => {
    (document.activeElement as HTMLElement | null)?.blur?.();
    audio.init();
    audio.startMusic();
    gameRef.current?.start(diff);
    setEnd(null);
    setScreen('play');
  }, [diff]);

  const setPaused = useCallback((v: boolean) => {
    if (gameRef.current) gameRef.current.paused = v;
    setScreen(v ? 'pause' : 'play');
  }, []);

  const toMenu = useCallback(() => {
    gameRef.current?.toAttract();
    setHi(gameRef.current?.hi ?? 0);
    setHud(null);
    setScreen('menu');
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code === 'Escape' || e.code === 'KeyP') {
        if (screen === 'play') setPaused(true);
        else if (screen === 'pause') setPaused(false);
      } else if (e.code === 'Enter' && (screen === 'menu' || screen === 'over')) play();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [screen, play, setPaused]);

  const toggleMute = () => {
    const m = !muted;
    setMuted(m);
    audio.setMuted(m);
  };

  return (
    <div ref={wrapRef} className="relative h-[100dvh] w-full select-none overflow-hidden bg-[#06101e]">
      <style>{STYLE}</style>
      <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full" style={{ imageRendering: 'pixelated' }} />
      {screen === 'menu' && <Menu diff={diff} setDiff={setDiff} hi={hi} muted={muted} onMute={toggleMute} onPlay={play} />}
      {(screen === 'play' || screen === 'pause') && hud && (
        <Hud h={hud} muted={muted} onMute={toggleMute} onPause={() => setPaused(true)} />
      )}
      {screen === 'play' && <TouchControls input={input} />}
      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={play} onMenu={toMenu} />}
      {screen === 'over' && end && <GameOver stats={end} onRetry={play} onMenu={toMenu} />}
    </div>
  );
}

import type { ReactNode } from 'react';
import { Bomb, Pause, Plane, RotateCw, Shield, Volume2, VolumeX } from 'lucide-react';
import type { HudState } from '../game/entities';

interface Props {
  h: HudState;
  muted: boolean;
  onMute: () => void;
  onPause: () => void;
}

const SH = { textShadow: '2px 2px 0 #000, 0 0 8px rgba(0,0,0,.6)' };
const pad = (n: number) => n.toString().padStart(7, '0');
const WEAPON = ['SIMPLE', 'DOBLE', 'TRIPLE'];

function Icons({ n, max, children }: { n: number; max: number; children: ReactNode }) {
  const shown = Math.min(n, max);
  return (
    <div className="flex items-center gap-0.5">
      {Array.from({ length: shown }, (_, i) => <span key={i}>{children}</span>)}
      {n > max && <span className="ml-1 text-xs">x{n}</span>}
    </div>
  );
}

export function Hud({ h, muted, onMute, onPause }: Props) {
  return (
    <div className="pointer-events-none absolute inset-0 select-none font-mono text-white" style={SH}>
      <div className="flex items-start justify-between gap-2 p-3 sm:p-4">
        <div>
          <div className="text-[10px] tracking-[0.3em] text-red-300">1UP</div>
          <div className="text-2xl font-black tabular-nums text-yellow-300 sm:text-3xl">{pad(h.score)}</div>
          <div className="text-[10px] tracking-wider text-sky-200">RÉCORD {pad(h.hi)}</div>
        </div>

        <div className="flex flex-col items-center pt-1">
          <div className="text-xs tracking-widest sm:text-sm">
            NIVEL <span className="text-yellow-300">{h.level}</span>
            <span className="hidden text-sky-200 sm:inline"> · {h.levelName.toUpperCase()}</span>
          </div>
          {h.boss !== null ? (
            <div className="mt-1.5 w-40 sm:w-72">
              <div className="mb-0.5 text-center text-[10px] tracking-[0.3em] text-red-300">FORTALEZA VOLANTE</div>
              <div className="h-3 overflow-hidden rounded-sm border-2 border-black bg-black/60">
                <div className="h-full bg-gradient-to-r from-red-600 via-orange-500 to-yellow-300 transition-[width]" style={{ width: `${h.boss * 100}%` }} />
              </div>
            </div>
          ) : (
            <div className="mt-1.5 h-1.5 w-28 overflow-hidden rounded-full border border-black/60 bg-black/50 sm:w-44">
              <div className="h-full bg-cyan-300" style={{ width: `${h.progress * 100}%` }} />
            </div>
          )}
        </div>

        <div className="flex flex-col items-end gap-1">
          <div className="pointer-events-auto flex gap-1.5">
            <button onClick={onMute} aria-label="Silenciar" className="rounded-md border-2 border-white/30 bg-black/50 p-1.5 hover:bg-black/70">
              {muted ? <VolumeX size={16} /> : <Volume2 size={16} />}
            </button>
            <button onClick={onPause} aria-label="Pausa" className="rounded-md border-2 border-white/30 bg-black/50 p-1.5 hover:bg-black/70">
              <Pause size={16} />
            </button>
          </div>
          <Icons n={h.lives} max={5}>
            <Plane size={16} className="-rotate-45 text-sky-300" fill="currentColor" />
          </Icons>
          <Icons n={h.bombs} max={5}>
            <Bomb size={15} className="text-orange-400" />
          </Icons>
          <Icons n={h.loops} max={3}>
            <RotateCw size={14} className="text-lime-300" />
          </Icons>
        </div>
      </div>

      <div className="absolute bottom-3 left-3 flex items-center gap-3 text-[11px] tracking-wider sm:bottom-4 sm:left-4">
        <span className="rounded border border-yellow-300/50 bg-black/50 px-2 py-0.5">
          ARMA <span className="text-yellow-300">{WEAPON[h.power - 1]}</span>
        </span>
        {h.shield > 0 && (
          <span className="flex items-center gap-1 rounded border border-cyan-300/60 bg-black/50 px-2 py-0.5 text-cyan-200">
            <Shield size={12} /> {Math.ceil(h.shield)}s
          </span>
        )}
      </div>

      {h.banner && (
        <div key={h.banner.title} className="r42-pop absolute inset-x-0 top-[30%] text-center">
          <div className="r42-title text-4xl font-black tracking-wider sm:text-6xl">{h.banner.title}</div>
          <div className="mt-2 text-sm tracking-[0.3em] text-sky-100 sm:text-base">{h.banner.sub.toUpperCase()}</div>
        </div>
      )}
    </div>
  );
}

import { Bomb, Crosshair, Move, Pause, Play, RotateCw, Trophy, Volume2, VolumeX } from 'lucide-react';
import clsx from 'clsx';
import { DIFFS } from '../game/entities';
import type { DiffKey } from '../game/entities';

interface Props {
  diff: DiffKey;
  setDiff: (d: DiffKey) => void;
  hi: number;
  muted: boolean;
  onMute: () => void;
  onPlay: () => void;
}

const SH = { textShadow: '2px 2px 0 #000' };

const CONTROLS = [
  { icon: Move, k: 'Flechas / WASD', v: 'Pilotar' },
  { icon: Crosshair, k: 'Automático', v: 'Ametralladoras' },
  { icon: RotateCw, k: 'Espacio / Shift', v: 'Rizo evasivo' },
  { icon: Bomb, k: 'X / B', v: 'Bomba' },
  { icon: Pause, k: 'P / Esc', v: 'Pausa' },
];

export function Menu({ diff, setDiff, hi, muted, onMute, onPlay }: Props) {
  return (
    <div className="absolute inset-0 flex items-center justify-center overflow-y-auto bg-gradient-to-b from-[#06101e]/70 via-transparent to-[#06101e]/80 p-4">
      <button
        onClick={onMute}
        aria-label="Silenciar"
        className="absolute right-4 top-4 rounded-lg border-2 border-yellow-300/50 bg-black/50 p-2 text-yellow-200 hover:bg-black/70"
      >
        {muted ? <VolumeX size={18} /> : <Volume2 size={18} />}
      </button>
      <div className="w-full max-w-xl rounded-2xl border-2 border-yellow-400/40 bg-[#0a1630]/75 p-6 text-center font-mono text-white shadow-[0_0_0_4px_rgba(0,0,0,.35),0_20px_60px_rgba(0,0,0,.6)] backdrop-blur-sm">
        <div className="mb-2 text-[11px] tracking-[0.5em] text-cyan-200/80">— PACÍFICO · 1942 —</div>
        <h1 className="r42-title text-5xl font-black leading-[0.95] tracking-tight sm:text-7xl">
          ESCUADRÓN
          <br />
          1942
        </h1>
        <p className="mx-auto mt-4 max-w-md text-sm leading-relaxed text-sky-100/90" style={SH}>
          Pilota tu caza bimotor sobre el océano, derriba escuadrones enemigos, esquiva con el rizo y hunde la fortaleza volante
          al final de cada nivel.
        </p>

        <div className="mt-5 text-[11px] tracking-widest text-yellow-200/80">DIFICULTAD</div>
        <div className="mt-2 grid grid-cols-3 gap-2">
          {(Object.keys(DIFFS) as DiffKey[]).map(k => (
            <button
              key={k}
              onClick={() => setDiff(k)}
              className={clsx(
                'rounded-lg border-2 px-2 py-2 text-left transition',
                diff === k ? 'border-yellow-300 bg-yellow-400/20 text-yellow-100' : 'border-white/15 bg-white/5 text-white/70 hover:border-white/40',
              )}
            >
              <div className="text-sm font-bold">{DIFFS[k].label}</div>
              <div className="text-[10px] opacity-80">{DIFFS[k].desc}</div>
            </button>
          ))}
        </div>

        <button
          onClick={onPlay}
          className="mx-auto mt-6 flex items-center gap-3 rounded-xl border-b-4 border-red-900 bg-gradient-to-b from-red-500 to-red-700 px-10 py-3 text-2xl font-black tracking-widest text-white shadow-[0_0_30px_rgba(255,80,60,.45)] transition hover:scale-105 active:translate-y-0.5"
          style={SH}
        >
          <Play size={24} fill="currentColor" /> Jugar
        </button>
        <div className="r42-blink mt-3 text-[11px] tracking-widest text-yellow-300">PULSA ENTER PARA DESPEGAR</div>

        <div className="mt-4 flex items-center justify-center gap-2 text-sm text-yellow-200" style={SH}>
          <Trophy size={16} /> RÉCORD <span className="tabular-nums text-white">{hi.toString().padStart(7, '0')}</span>
        </div>

        <div className="mt-4 grid grid-cols-2 gap-x-4 gap-y-1 text-left text-[11px] text-sky-100/80 sm:grid-cols-3">
          {CONTROLS.map(({ icon: Icon, k, v }) => (
            <div key={k} className="flex items-center gap-1.5">
              <Icon size={13} className="shrink-0 text-yellow-300" />
              <span className="text-white">{k}</span>
              <span className="opacity-70">· {v}</span>
            </div>
          ))}
        </div>
        <div className="mt-3 flex flex-wrap justify-center gap-2 text-[10px]">
          <span className="rounded bg-red-600/80 px-1.5 py-0.5">P · Arma</span>
          <span className="rounded bg-cyan-600/80 px-1.5 py-0.5">S · Escudo</span>
          <span className="rounded bg-orange-500/80 px-1.5 py-0.5">B · Bomba</span>
          <span className="rounded bg-green-600/80 px-1.5 py-0.5">1 · Vida</span>
        </div>
      </div>
    </div>
  );
}

import { useEffect } from 'react';
import type { ReactNode } from 'react';
import confetti from 'canvas-confetti';
import { Home, Play, RotateCcw, Trophy } from 'lucide-react';
import type { EndStats } from '../game/entities';

const SH = { textShadow: '2px 2px 0 #000' };
const BTN = 'flex items-center justify-center gap-2 rounded-xl border-b-4 px-6 py-2.5 font-black tracking-widest transition hover:scale-105';

function Panel({ children }: { children: ReactNode }) {
  return (
    <div className="absolute inset-0 flex items-center justify-center bg-[#06101e]/60 p-4 backdrop-blur-[2px]">
      <div className="w-full max-w-md rounded-2xl border-2 border-yellow-400/40 bg-[#0a1630]/85 p-6 text-center font-mono text-white shadow-2xl" style={SH}>
        {children}
      </div>
    </div>
  );
}

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <Panel>
      <div className="r42-title text-5xl font-black tracking-widest">PAUSA</div>
      <div className="mt-2 text-xs tracking-widest text-sky-200">EL ESCUADRÓN ESPERA TUS ÓRDENES</div>
      <div className="mt-6 flex flex-col gap-3">
        <button onClick={onResume} className={`${BTN} border-red-900 bg-red-600 hover:bg-red-500`}>
          <Play size={18} fill="currentColor" /> Continuar
        </button>
        <button onClick={onRestart} className={`${BTN} border-sky-900 bg-sky-700 hover:bg-sky-600`}>
          <RotateCcw size={18} /> Reiniciar
        </button>
        <button onClick={onMenu} className={`${BTN} border-slate-900 bg-slate-700 hover:bg-slate-600`}>
          <Home size={18} /> Menú
        </button>
      </div>
      <div className="mt-4 text-[11px] text-white/60">Pulsa P o Esc para continuar</div>
    </Panel>
  );
}

export function GameOver({ stats, onRetry, onMenu }: { stats: EndStats; onRetry: () => void; onMenu: () => void }) {
  useEffect(() => {
    if (!stats.newRecord) return;
    const t = window.setTimeout(() => {
      confetti({ particleCount: 140, spread: 80, origin: { y: 0.4 }, colors: ['#ffd23c', '#ff8a1e', '#d8343c', '#8ef0ff'] });
    }, 300);
    return () => window.clearTimeout(t);
  }, [stats.newRecord]);

  const rows: [string, string][] = [
    ['NIVEL ALCANZADO', String(stats.level)],
    ['DERRIBOS', String(stats.kills)],
    ['PRECISIÓN', `${stats.accuracy}%`],
    ['RÉCORD', stats.hi.toString().padStart(7, '0')],
  ];
  return (
    <Panel>
      <div className="text-xs tracking-[0.4em] text-red-300">FIN DE LA MISIÓN</div>
      <div className="r42-title mt-1 text-5xl font-black">DERRIBADO</div>
      {stats.newRecord && (
        <div className="r42-blink mt-3 flex items-center justify-center gap-2 text-lg font-black text-yellow-300">
          <Trophy size={20} /> ¡NUEVO RÉCORD!
        </div>
      )}
      <div className="mt-4 text-4xl font-black tabular-nums text-yellow-300">{stats.score.toString().padStart(7, '0')}</div>
      <div className="mx-auto mt-4 grid max-w-xs grid-cols-2 gap-y-1 text-left text-sm">
        {rows.map(([k, v]) => (
          <div key={k} className="contents">
            <span className="text-sky-200/80">{k}</span>
            <span className="text-right tabular-nums">{v}</span>
          </div>
        ))}
      </div>
      <div className="mt-6 flex flex-col gap-3 sm:flex-row sm:justify-center">
        <button onClick={onRetry} className={`${BTN} border-red-900 bg-red-600 hover:bg-red-500`}>
          <RotateCcw size={18} /> Reintentar
        </button>
        <button onClick={onMenu} className={`${BTN} border-slate-900 bg-slate-700 hover:bg-slate-600`}>
          <Home size={18} /> Menú
        </button>
      </div>
    </Panel>
  );
}

import { useRef, useState } from 'react';
import type { PointerEvent } from 'react';
import { Bomb, RotateCw } from 'lucide-react';
import type { Input } from '../game/input';

const R = 48;

export function TouchControls({ input }: { input: Input | null }) {
  const [touch] = useState(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0));
  const [knob, setKnob] = useState({ x: 0, y: 0 });
  const base = useRef<HTMLDivElement>(null);
  const pid = useRef<number | null>(null);

  if (!touch || !input) return null;

  const move = (e: PointerEvent) => {
    if (pid.current !== e.pointerId || !base.current) return;
    const r = base.current.getBoundingClientRect();
    let x = e.clientX - (r.left + r.width / 2), y = e.clientY - (r.top + r.height / 2);
    const m = Math.hypot(x, y);
    if (m > R) { x = (x / m) * R; y = (y / m) * R; }
    setKnob({ x, y });
    input.joy.x = x / R;
    input.joy.y = y / R;
  };
  const end = (e: PointerEvent) => {
    if (pid.current !== e.pointerId) return;
    pid.current = null;
    setKnob({ x: 0, y: 0 });
    input.joy.x = 0;
    input.joy.y = 0;
  };

  const btn = 'flex h-16 w-16 flex-col items-center justify-center rounded-full border-2 bg-black/40 text-[9px] font-bold tracking-wider text-white active:scale-95';

  return (
    <div className="pointer-events-none absolute inset-x-0 bottom-0 flex items-end justify-between p-5 font-mono">
      <div
        ref={base}
        className="pointer-events-auto relative h-32 w-32 touch-none rounded-full border-2 border-white/30 bg-black/25"
        onPointerDown={e => { pid.current = e.pointerId; (e.target as HTMLElement).setPointerCapture(e.pointerId); move(e); }}
        onPointerMove={move}
        onPointerUp={end}
        onPointerCancel={end}
      >
        <div
          className="absolute left-1/2 top-1/2 h-12 w-12 rounded-full border-2 border-yellow-200/70 bg-yellow-300/40"
          style={{ transform: `translate(calc(-50% + ${knob.x}px), calc(-50% + ${knob.y}px))` }}
        />
      </div>
      <div className="pointer-events-auto mb-2 flex gap-3">
        <button className={`${btn} border-orange-300/70`} onPointerDown={() => input.requestBomb()}>
          <Bomb size={20} /> BOMBA
        </button>
        <button className={`${btn} -translate-y-8 border-lime-300/70`} onPointerDown={() => input.requestLoop()}>
          <RotateCw size={20} /> RIZO
        </button>
      </div>
    </div>
  );
}

// Comportamiento enemigo: trayectorias, disparos y patrones del jefe.
import { STATS, clamp, makeEnemy } from './entities';
import type { Bullet, Diff, Enemy, Player } from './entities';

export const SCROLL = 26;

/** Lo que la IA necesita del motor. */
export interface AiWorld {
  W: number; H: number; level: number; time: number; diff: Diff; p: Player;
  enemies: Enemy[]; eb: Bullet[]; dying: boolean;
}

export function shoot(g: AiWorld, x: number, y: number, a: number, s: number, r: number) {
  g.eb.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, r, life: 8 });
}

export function moveEnemy(g: AiWorld, e: Enemy, dt: number, attract: boolean) {
  const { p, W, H } = g;
  const ox = e.x, oy = e.y;
  switch (e.mode) {
    case 'dive':
      e.y += e.vy * dt;
      if (e.d && e.y > H * 0.38) e.a += e.dir * 85 * dt;
      e.x = e.a + Math.sin(e.t * 2 + e.c) * e.b;
      break;
    case 'swoop':
      e.x = e.a + e.dir * e.c * e.t;
      e.y = e.b + H * (0.95 * e.t - 0.43 * e.t * e.t);
      break;
    case 'loop':
      if (e.b === 0) {
        e.y += e.vy * dt;
        if (e.y > e.a) { e.b = 1; e.vx = e.x + 26 * e.dir; e.a = e.y; e.c = 0; }
      } else if (e.b === 1) {
        e.c += dt * 4.2;
        e.x = e.vx - e.dir * 26 * Math.cos(e.c);
        e.y = e.a + 26 * Math.sin(e.c);
        if (e.c >= Math.PI * 2) e.b = 2;
      } else e.y += e.vy * 1.3 * dt;
      break;
    case 'chase':
      e.vx = clamp(e.vx + Math.sign((p.alive ? p.x : W / 2) - e.x) * 140 * dt, -75, 75);
      e.x += e.vx * dt;
      e.y += e.vy * dt;
      break;
    case 'drift':
      e.y += e.vy * dt;
      e.x += Math.sin(e.t * 0.7) * 10 * dt;
      break;
    case 'boat':
      e.y += SCROLL * dt;
      e.x += e.vx * dt;
      e.aim = Math.atan2(p.y - e.y, p.x - e.x);
      break;
    case 'boss':
      updateBoss(g, e, dt, attract);
      break;
  }
  if (e.kind === 'zero' || e.kind === 'red' || e.kind === 'mini') {
    const dx = e.x - ox, dy = e.y - oy;
    if (dx * dx + dy * dy > 1e-4) {
      let d = Math.atan2(dy, dx) - e.aim;
      d = Math.atan2(Math.sin(d), Math.cos(d));
      e.aim += d * Math.min(1, dt * 10);
    }
  }
  if (!attract && p.alive && e.kind !== 'boss' && e.y > 6 && e.y < H * 0.7) {
    e.fireT -= dt * g.diff.fire * (1 + (g.level - 1) * 0.12);
    if (e.fireT <= 0) { e.fireT = STATS[e.kind].fire * (0.7 + Math.random() * 0.6); enemyFire(g, e); }
  }
}

function enemyFire(g: AiWorld, e: Enemy) {
  const spd = 92 * g.diff.bspd * (1 + (g.level - 1) * 0.06);
  const ang = Math.atan2(g.p.y - e.y, g.p.x - e.x);
  if ((e.kind === 'zero' || e.kind === 'mini') && Math.random() < 0.65) shoot(g, e.x, e.y + 5, ang, spd, 2);
  else if (e.kind === 'red') shoot(g, e.x, e.y + 5, ang, spd * 1.1, 2);
  else if (e.kind === 'bomber') for (const o of [-0.28, 0, 0.28]) shoot(g, e.x, e.y + 8, ang + o, spd * 0.9, 3);
  else if (e.kind === 'boat') shoot(g, e.x + Math.cos(e.aim) * 6, e.y + Math.sin(e.aim) * 6, ang, spd, 2);
}

const PATTERN_LEN = [2.6, 2.8, 2.6, 2.2];

function updateBoss(g: AiWorld, e: Enemy, dt: number, attract: boolean) {
  const ty = Math.min(72, g.H * 0.25);
  if (g.dying) { e.y += 8 * dt; e.x += Math.sin(g.time * 20) * 10 * dt; return; }
  if (e.b === 0) { e.y += 32 * dt; if (e.y >= ty) e.b = 1; return; }
  e.d += dt;
  e.x = g.W / 2 + Math.sin(e.d * 0.45) * g.W * 0.28;
  e.y = ty + Math.sin(e.d * 0.9) * 8;
  if (attract || !g.p.alive) return;
  const rage = e.hp < e.maxHp * 0.5 ? 1.45 : 1;
  const spd = 88 * g.diff.bspd * (1 + (g.level - 1) * 0.05);
  const pa = Math.atan2(g.p.y - e.y, g.p.x - e.x);
  const pat = e.c % 4;
  e.a += dt;
  e.fireT -= dt * rage * Math.sqrt(g.diff.fire);
  if (e.fireT <= 0) {
    if (pat === 0) {
      // abanico apuntado
      for (let i = -2; i <= 2; i++) shoot(g, e.x, e.y + 16, pa + i * 0.2, spd, 3);
      e.fireT = 0.8;
    } else if (pat === 1) {
      // espiral
      for (let k = 0; k < 3; k++) shoot(g, e.x, e.y + 4, e.a * 3.1 + (k * Math.PI * 2) / 3, spd * 0.8, 3);
      e.fireT = 0.09;
    } else if (pat === 2) {
      // torretas de las alas
      for (const tx of [-22, 22, -12, 12]) {
        const x = e.x + tx, y = e.y + 8;
        shoot(g, x, y, Math.atan2(g.p.y - y, g.p.x - x), spd * 1.1, 2);
      }
      e.fireT = 0.55;
    } else {
      // lanza cazas de escolta
      for (const s of [-1, 1]) g.enemies.push(makeEnemy('mini', e.x + s * 22, e.y + 6, 'chase', { vy: 70, vx: s * 40, fireT: 1.2 }));
      e.fireT = 1.0;
    }
  }
  if (e.a > PATTERN_LEN[pat]) { e.a = 0; e.c++; e.fireT = 0.5; }
}

// Sonido chiptune con Web Audio API: efectos y una marcha en bucle.

const mtof = (m: number) => 440 * Math.pow(2, (m - 69) / 12);
const LEAD = [
  69, 0, 72, 0, 76, 74, 72, 0, 72, 0, 69, 0, 65, 67, 69, 0,
  71, 0, 74, 0, 79, 77, 74, 0, 76, 0, 75, 76, 71, 0, 68, 0,
];
const BASS = [45, 45, 41, 41, 43, 43, 40, 40];

class AudioFx {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private music: GainNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private timer = 0;
  private step = 0;
  private nextT = 0;
  private lastShot = 0;
  muted = false;

  init() {
    if (this.ctx) { void this.ctx.resume(); return; }
    const w = window as unknown as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext };
    const AC = w.AudioContext || w.webkitAudioContext;
    if (!AC) return;
    try { this.ctx = new AC(); } catch { return; }
    const ctx = this.ctx;
    this.master = ctx.createGain(); this.music = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55; this.music.gain.value = 0.3;
    this.master.connect(ctx.destination); this.music.connect(this.master);
    const buf = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    this.noiseBuf = buf;
  }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.02);
  }

  private tone(f: number, dur: number, type: OscillatorType, vol: number, f2?: number, delay = 0, dest?: AudioNode) {
    const c = this.ctx;
    if (!c || !this.master) return;
    const t = c.currentTime + Math.max(0, delay);
    const o = c.createOscillator(), g = c.createGain();
    o.type = type;
    o.frequency.setValueAtTime(f, t);
    if (f2) o.frequency.exponentialRampToValueAtTime(Math.max(20, f2), t + dur);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0008, t + dur);
    o.connect(g).connect(dest ?? this.master);
    o.start(t); o.stop(t + dur + 0.02);
  }

  private noise(dur: number, vol: number, freq: number, f2?: number, delay = 0, dest?: AudioNode) {
    const c = this.ctx;
    if (!c || !this.master || !this.noiseBuf) return;
    const t = c.currentTime + Math.max(0, delay);
    const s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain();
    s.buffer = this.noiseBuf;
    f.type = 'lowpass';
    f.frequency.setValueAtTime(freq, t);
    if (f2) f.frequency.exponentialRampToValueAtTime(f2, t + dur);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0008, t + dur);
    s.connect(f).connect(g).connect(dest ?? this.master);
    s.start(t); s.stop(t + dur + 0.02);
  }

  shoot() {
    const c = this.ctx;
    if (!c || c.currentTime - this.lastShot < 0.09) return;
    this.lastShot = c.currentTime;
    this.tone(1300, 0.05, 'square', 0.022, 520);
  }
  hit() { this.tone(320, 0.04, 'square', 0.03, 160); }
  explode(big = false) {
    this.noise(big ? 0.9 : 0.35, big ? 0.55 : 0.3, big ? 1000 : 2200, 70);
    this.tone(big ? 90 : 150, big ? 0.6 : 0.22, 'sawtooth', 0.12, 30);
  }
  power() { [523, 659, 784, 1047].forEach((f, i) => this.tone(f, 0.09, 'square', 0.07, undefined, i * 0.06)); }
  loop() { this.tone(220, 0.7, 'triangle', 0.14, 990); this.noise(0.6, 0.07, 3500, 500); }
  bomb() { this.noise(1.5, 0.7, 700, 40); this.tone(70, 1.3, 'sine', 0.45, 24); }
  die() { this.noise(1.2, 0.6, 1500, 60); this.tone(400, 1.0, 'square', 0.1, 40); }
  siren() {
    for (let i = 0; i < 3; i++) {
      this.tone(520, 0.4, 'square', 0.06, 880, i * 0.8);
      this.tone(880, 0.4, 'square', 0.06, 520, i * 0.8 + 0.4);
    }
  }
  fanfare() { [60, 64, 67, 72, 67, 72].forEach((m, i) => this.tone(mtof(m + 12), 0.16, 'square', 0.07, undefined, i * 0.12)); }

  startMusic() {
    if (!this.ctx || this.timer) return;
    this.nextT = this.ctx.currentTime + 0.1;
    this.step = 0;
    this.timer = window.setInterval(() => this.schedule(), 90);
  }

  private schedule() {
    const c = this.ctx;
    if (!c || !this.music) return;
    const st = 0.14;
    if (this.nextT < c.currentTime) this.nextT = c.currentTime + 0.05;
    while (this.nextT < c.currentTime + 0.3) {
      const s = this.step % 32;
      const dl = this.nextT - c.currentTime;
      const n = LEAD[s];
      if (n) this.tone(mtof(n), st * 0.9, 'square', 0.05, undefined, dl, this.music);
      if (s % 2 === 0) this.tone(mtof(BASS[Math.floor(s / 4)] + (s % 4 === 2 ? 12 : 0)), st * 1.6, 'triangle', 0.16, undefined, dl, this.music);
      if (s % 4 === 0) this.tone(140, 0.12, 'sine', 0.25, 45, dl, this.music);
      if (s % 2 === 1) this.noise(0.04, 0.05, 7000, undefined, dl, this.music);
      this.nextT += st;
      this.step++;
    }
  }

  stopMusic() {
    if (this.timer) window.clearInterval(this.timer);
    this.timer = 0;
  }

  dispose() {
    this.stopMusic();
    if (this.ctx) void this.ctx.close().catch(() => undefined);
    this.ctx = this.master = this.music = null;
  }
}

export const audio = new AudioFx();

// Motor del juego: bucle, director de oleadas, colisiones y composición final.
import { audio } from './audio';
import { DIFFS, LOOP_T, STATS, clamp, makeEnemy } from './entities';
import type { Bullet, Diff, DiffKey, Enemy, EndStats, HudState, Particle, Player, PowerUp, PUType } from './entities';
import type { Input } from './input';
import { getSprites } from './sprites';
import { PALETTES, World } from './world';
import { pickWave, spawnWave } from './waves';
import { SCROLL, moveEnemy } from './ai';
import type { AiWorld } from './ai';
import * as R from './render';

const HI_KEY = 'nona-retro1942-hi';
const PSPEED = 128;
const LEVEL_LEN = 46;

export interface GameCallbacks { onHud: (h: HudState) => void; onEnd: (s: EndStats) => void; }
type Phase = 'waves' | 'warn' | 'boss' | 'dying' | 'clear';

export class Game implements AiWorld {
  W = 427; H = 267; time = 0; level = 1; score = 0; hi = 0;
  mode: 'attract' | 'play' | 'over' = 'attract';
  paused = false;
  diff: Diff = DIFFS.normal;
  p: Player;
  enemies: Enemy[] = []; pb: Bullet[] = []; eb: Bullet[] = []; parts: Particle[] = []; pups: PowerUp[] = [];
  private kills = 0; private shots = 0; private hits = 0;
  private phase: Phase = 'waves'; private phaseT = 0; private levelT = 0; private waveT = 0.3; private waveN = 0;
  private boss: Enemy | null = null;
  private groups = new Map<number, number>(); private gid = 0;
  private shake = 0; private flash = 0; private hudT = 0; private dieFx = 0;
  private banner: { title: string; sub: string } | null = null; private bannerT = 0;
  private k = 3; private raf = 0; private last = 0;
  private cv: HTMLCanvasElement; private sctx: CanvasRenderingContext2D;
  private buf: HTMLCanvasElement; private b: CanvasRenderingContext2D;
  private scan: CanvasPattern | null = null; private vignette: CanvasGradient | null = null;
  private world: World;

  constructor(canvas: HTMLCanvasElement, private input: Input, private cb: GameCallbacks) {
    this.cv = canvas; this.sctx = canvas.getContext('2d')!;
    this.buf = document.createElement('canvas'); this.b = this.buf.getContext('2d')!;
    this.world = new World(PALETTES[0]);
    this.p = this.newPlayer(3);
    try { this.hi = Number(localStorage.getItem(HI_KEY)) || 0; } catch { this.hi = 0; }
    getSprites();
  }

  get dying() { return this.phase === 'dying'; }

  run() { this.last = performance.now(); this.raf = requestAnimationFrame(this.loop); }

  destroy() { cancelAnimationFrame(this.raf); this.enemies = []; this.parts = []; this.eb = []; this.pb = []; }

  resize(cssW: number, cssH: number) {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const pw = Math.max(1, Math.round(cssW * dpr)), ph = Math.max(1, Math.round(cssH * dpr));
    this.cv.width = pw; this.cv.height = ph;
    // escala entera para píxeles nítidos: ~280 px lógicos de alto y al menos 220 de ancho
    const k = Math.max(1, Math.min(Math.round(ph / 280), Math.floor(pw / 220)));
    this.k = k; this.W = Math.ceil(pw / k); this.H = Math.ceil(ph / k);
    this.buf.width = this.W; this.buf.height = this.H;
    const sc = Object.assign(document.createElement('canvas'), { width: 1, height: Math.max(2, k) }), x = sc.getContext('2d')!;
    x.fillStyle = 'rgba(0,0,20,0.16)'; x.fillRect(0, sc.height - 1, 1, 1);
    this.scan = this.sctx.createPattern(sc, 'repeat');
    const g = this.sctx.createRadialGradient(pw / 2, ph / 2, Math.min(pw, ph) * 0.35, pw / 2, ph / 2, Math.max(pw, ph) * 0.75);
    g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(0,0,12,0.5)');
    this.vignette = g;
    this.p.x = clamp(this.p.x, 9, this.W - 9);
    this.p.y = clamp(this.p.y, 16, this.H - 12);
    this.world.ensure(this.W, this.H);
  }

  start(dk: DiffKey) {
    this.diff = DIFFS[dk];
    this.mode = 'play'; this.paused = false;
    this.p = this.newPlayer(this.diff.lives);
    this.enemies = []; this.pb = []; this.eb = []; this.parts = []; this.pups = [];
    this.groups.clear();
    this.score = this.kills = this.shots = this.hits = 0;
    this.boss = null; this.shake = this.flash = 0;
    this.setLevel(1);
    this.cb.onHud(this.hud());
  }

  toAttract() {
    this.mode = 'attract'; this.paused = false;
    this.p = this.newPlayer(3);
    this.eb = []; this.pups = []; this.banner = null; this.boss = null;
    this.enemies = this.enemies.filter(e => e.kind !== 'boss');
    this.setLevel(1);
  }

  private newPlayer(lives: number): Player {
    return { x: this.W / 2, y: this.H - 34, alive: true, lives, bombs: 2, loops: 3, power: 1, shield: 0, inv: 2.2, loopT: 0, fireT: 0, respawnT: 0, tilt: 0 };
  }

  private setLevel(n: number) {
    const pal = PALETTES[(n - 1) % PALETTES.length];
    this.level = n;
    this.world.setPalette(pal);
    this.phase = 'waves';
    this.levelT = this.phaseT = this.waveN = 0;
    this.waveT = 0.2;
    if (this.mode === 'play') this.showBanner(`NIVEL ${n}`, pal.name, 2.4);
  }

  private showBanner(title: string, sub: string, t: number) { this.banner = { title, sub }; this.bannerT = t; }

  private loop = (ts: number) => {
    this.raf = requestAnimationFrame(this.loop);
    const dt = Math.min(0.05, Math.max(0, (ts - this.last) / 1000));
    this.last = ts;
    if (!this.paused) this.update(dt);
    this.draw();
  };

  private update(dt: number) {
    const attract = this.mode !== 'play';
    this.time += dt;
    this.world.update(dt, this.W, this.H, SCROLL);
    this.updatePlayer(dt);
    this.updateDirector(dt, attract);
    for (const e of this.enemies) {
      if (e.t < 0) { e.t += dt; continue; }
      e.t += dt;
      if (e.flash > 0) e.flash -= dt;
      moveEnemy(this, e, dt, attract);
      const off = e.y > this.H + 40 || e.x < -70 || e.x > this.W + 70 || (e.y < -60 && e.t > 2.5);
      if (off && e.kind !== 'boss') { e.dead = true; if (e.group) this.groups.set(e.group, -99); }
    }
    this.enemies = this.enemies.filter(e => !e.dead);
    for (const b of this.pb) { b.x += b.vx * dt; b.y += b.vy * dt; b.life -= dt; }
    for (const b of this.eb) { b.x += b.vx * dt; b.y += b.vy * dt; b.life -= dt; }
    this.collide();
    this.pb = this.pb.filter(b => b.life > 0 && b.y > -10);
    this.eb = this.eb.filter(b => b.life > 0 && b.x > -10 && b.x < this.W + 10 && b.y > -10 && b.y < this.H + 10);
    for (const u of this.pups) { u.t += dt; u.y += 22 * dt; u.x += Math.sin(u.t * 3) * 14 * dt; }
    this.pups = this.pups.filter(u => !u.taken && u.y < this.H + 10);
    this.parts = R.updateParticles(this.parts, dt);
    this.shake = Math.max(0, this.shake - dt * 22);
    this.flash = Math.max(0, this.flash - dt * 1.8);
    if (this.bannerT > 0 && (this.bannerT -= dt) <= 0) this.banner = null;
    if ((this.hudT -= dt) <= 0 && this.mode === 'play') { this.hudT = 0.1; this.cb.onHud(this.hud()); }
  }

  private updatePlayer(dt: number) {
    const p = this.p;
    const loopReq = this.input.consumeLoop(), bombReq = this.input.consumeBomb();
    if (this.mode === 'over') return;
    p.inv -= dt;
    p.shield = Math.max(0, p.shield - dt);
    p.loopT = Math.max(0, p.loopT - dt);
    if (this.mode === 'attract') {
      // piloto automático detrás del menú
      const tx = this.W / 2 + Math.sin(this.time * 0.6) * this.W * 0.32;
      const ty = this.H * 0.78 + Math.sin(this.time * 1.3) * 12;
      p.tilt = clamp((tx - p.x) * 0.08, -1, 1);
      p.x += (tx - p.x) * Math.min(1, dt * 2.5);
      p.y += (ty - p.y) * Math.min(1, dt * 2);
      p.alive = true; p.inv = 0; p.power = 2;
    } else if (p.alive) {
      const a = this.input.axis();
      p.x = clamp(p.x + a.x * PSPEED * dt, 9, this.W - 9);
      p.y = clamp(p.y + a.y * PSPEED * dt, 16, this.H - 12);
      p.tilt += (a.x - p.tilt) * Math.min(1, dt * 10);
      if (loopReq && p.loops > 0 && p.loopT <= 0) { p.loopT = LOOP_T; p.loops--; audio.loop(); }
      if (bombReq && p.bombs > 0) this.bomb();
    } else if ((p.respawnT -= dt) <= 0) {
      if (p.lives <= 0) { this.gameOver(); return; }
      Object.assign(p, { alive: true, x: this.W / 2, y: this.H - 30, inv: 2.5, loops: 3 });
    }
    p.fireT -= dt;
    if (p.alive && p.loopT <= 0 && p.fireT <= 0) { p.fireT = 0.1; this.fire(); }
  }

  private fire() {
    const p = this.p, v = -300;
    const add = (x: number, y: number, vx: number, vy: number) => this.pb.push({ x, y, vx, vy, r: 3, life: 1.2 });
    add(p.x - 2, p.y - 8, 0, v); add(p.x + 2, p.y - 8, 0, v);
    if (p.power >= 2) { add(p.x - 7, p.y - 4, 0, v); add(p.x + 7, p.y - 4, 0, v); }
    if (p.power >= 3) { add(p.x - 6, p.y - 4, -75, v * 0.95); add(p.x + 6, p.y - 4, 75, v * 0.95); }
    if (this.mode === 'play') { this.shots += p.power * 2; audio.shoot(); }
  }

  private updateDirector(dt: number, attract: boolean) {
    this.levelT += dt;
    this.phaseT += dt;
    if (this.phase === 'waves') {
      if ((this.waveT -= dt) <= 0) {
        spawnWave(pickWave(this.level, this.waveN++), {
          W: this.W, H: this.H, level: this.level,
          add: e => { this.enemies.push(e); },
          newGroup: n => { this.groups.set(++this.gid, n); return this.gid; },
        });
        const base = Math.max(1.1, 2.6 - this.level * 0.18) / Math.sqrt(attract ? 0.8 : this.diff.fire);
        this.waveT = this.waveN < 5 && !attract ? 0.8 : base * (0.8 + Math.random() * 0.4);
      }
      if (!attract && this.levelT > LEVEL_LEN) {
        this.phase = 'warn'; this.phaseT = 0;
        this.showBanner('¡ALERTA!', 'Fortaleza volante aproximándose', 2.8);
        audio.siren();
      }
    } else if (this.phase === 'warn' && this.phaseT > 3) {
      const hp = Math.round(STATS.boss.hp * (1 + (this.level - 1) * 0.45) * this.diff.hp);
      this.boss = makeEnemy('boss', this.W / 2, -40, 'boss', { hp, variant: (this.level - 1) % 4, fireT: 1.2 });
      this.enemies.push(this.boss);
      this.phase = 'boss';
    } else if (this.phase === 'dying' && this.boss) {
      // cadena de explosiones y derribo final del jefe
      const e = this.boss;
      if ((this.dieFx -= dt) <= 0) {
        this.dieFx = 0.09;
        R.explode(this.parts, e.x + (Math.random() - 0.5) * 56, e.y + (Math.random() - 0.5) * 24, 1 + Math.random());
        this.shake = Math.max(this.shake, 4);
        audio.explode(false);
      }
      if (this.phaseT > 2.2) {
        const bonus = 10000 * this.level;
        R.explode(this.parts, e.x, e.y, 4);
        R.ring(this.parts, e.x, e.y, 90, '#ffffff', 0.7);
        e.dead = true;
        this.score += e.score + bonus;
        this.flash = 0.9; this.shake = 16;
        audio.explode(true); audio.fanfare();
        this.drop(e.x - 14, e.y, 'P'); this.drop(e.x + 14, e.y, 'B');
        if (this.level % 2 === 0) this.drop(e.x, e.y + 10, '1');
        this.boss = null;
        this.phase = 'clear'; this.phaseT = 0;
        this.showBanner('¡FORTALEZA DERRIBADA!', `Bonificación +${bonus.toLocaleString('es-ES')}`, 3.6);
      }
    } else if (this.phase === 'clear' && this.phaseT > 4.5) {
      this.setLevel(this.level + 1);
    }
  }

  private hitTest(e: Enemy, x: number, y: number, pad: number) {
    const dx = x - e.x, dy = y - e.y;
    if (e.kind === 'boss') return (Math.abs(dx) < 30 + pad && Math.abs(dy + 3) < 6 + pad) || (Math.abs(dx) < 6 + pad && Math.abs(dy) < 19 + pad);
    return dx * dx + dy * dy < (e.r + pad) * (e.r + pad);
  }

  private collide() {
    const p = this.p;
    for (const b of this.pb) {
      for (const e of this.enemies) {
        if (e.t < 0 || e.dead || e.hp <= 0 || e.y < -20) continue;
        if (this.hitTest(e, b.x, b.y, 2)) { b.life = 0; this.damage(e, 1, b.x, b.y); break; }
      }
    }
    if (this.mode !== 'play' || !p.alive || p.loopT > 0) return; // el rizo esquiva todo
    const pr = p.shield > 0 ? 11 : 2.5;
    for (const b of this.eb) {
      if (b.life <= 0 || (b.x - p.x) ** 2 + (b.y - p.y) ** 2 >= (b.r + pr) ** 2) continue;
      if (p.shield > 0) { b.life = 0; R.sparks(this.parts, b.x, b.y, 4, '#8ef0ff'); }
      else if (p.inv <= 0) { b.life = 0; this.die(); return; }
    }
    for (const e of this.enemies) {
      if (e.t < 0 || e.ground || e.hp <= 0 || e.dead || !this.hitTest(e, p.x, p.y, p.shield > 0 ? 9 : 3)) continue;
      if (p.shield > 0) this.damage(e, 3, p.x, p.y - 6);
      else if (p.inv <= 0) { this.damage(e, 8, p.x, p.y); this.die(); return; }
    }
    for (const u of this.pups) {
      if (!u.taken && Math.hypot(u.x - p.x, u.y - p.y) < 12) { u.taken = true; this.pickup(u.type); }
    }
  }

  private damage(e: Enemy, n: number, x: number, y: number) {
    e.hp -= n;
    e.flash = 0.06;
    if (this.mode === 'play') this.hits++;
    R.sparks(this.parts, x, y, 3, '#fff3a0');
    if (e.hp <= 0) this.kill(e);
    else if (this.mode === 'play') audio.hit();
  }

  private kill(e: Enemy) {
    if (e.kind === 'boss') {
      this.phase = 'dying'; this.phaseT = 0; this.dieFx = 0; this.eb = [];
      for (const o of this.enemies) if (o.kind === 'mini') { o.dead = true; R.explode(this.parts, o.x, o.y, 1); }
      return;
    }
    e.dead = true;
    const big = e.kind === 'bomber' || e.kind === 'boat';
    R.explode(this.parts, e.x, e.y, big ? 2.2 : 1.1);
    if (this.mode !== 'play') return;
    this.shake = Math.max(this.shake, big ? 6 : 2.5);
    audio.explode(big);
    this.score += e.score;
    this.kills++;
    R.floatText(this.parts, e.x, e.y - 6, String(e.score));
    if (e.group) {
      const n = (this.groups.get(e.group) ?? 0) - 1;
      this.groups.set(e.group, n);
      if (n === 0) {
        this.score += 1000;
        this.drop(e.x, e.y, 'P');
        R.floatText(this.parts, e.x, e.y - 16, '¡ESCUADRÓN! +1000', '#ffd23c');
      }
    } else if (e.kind === 'bomber') this.drop(e.x, e.y, Math.random() < 0.5 ? 'S' : 'B');
    else if (e.kind === 'boat' && Math.random() < 0.3) this.drop(e.x, e.y, 'B');
    else if (Math.random() < 0.035) this.drop(e.x, e.y, Math.random() < 0.15 ? '1' : 'P');
  }

  private drop(x: number, y: number, type: PUType) {
    this.pups.push({ x: clamp(x, 10, this.W - 10), y, t: 0, type, taken: false });
  }

  private pickup(type: PUType) {
    const p = this.p;
    let msg = '';
    audio.power();
    this.score += 500;
    if (type === 'P') {
      if (p.power < 3) { p.power++; msg = p.power === 2 ? '¡DISPARO DOBLE!' : '¡DISPARO TRIPLE!'; }
      else { this.score += 1500; msg = '+2000'; }
    } else if (type === 'S') { p.shield = 10; msg = '¡ESCUDO!'; }
    else if (type === 'B') { p.bombs = Math.min(5, p.bombs + 1); msg = '+1 BOMBA'; }
    else { p.lives++; msg = '¡VIDA EXTRA!'; }
    R.floatText(this.parts, p.x, p.y - 16, msg, '#7fffd4');
    R.ring(this.parts, p.x, p.y, 22, '#7fffd4', 0.4);
  }

  private bomb() {
    const p = this.p;
    p.bombs--;
    this.flash = 1; this.shake = 12;
    audio.bomb();
    for (const b of this.eb) { R.sparks(this.parts, b.x, b.y, 2, '#ffe080'); this.score += 10; }
    this.eb = [];
    R.ring(this.parts, p.x, p.y, Math.max(this.W, this.H), '#ffffff', 0.7);
    for (const e of this.enemies) {
      if (e.t >= 0 && e.hp > 0 && e.y > -10 && !e.dead) this.damage(e, e.kind === 'boss' ? 30 : 20, e.x, e.y);
    }
  }

  private die() {
    const p = this.p;
    Object.assign(p, { alive: false, lives: p.lives - 1, power: Math.max(1, p.power - 1), respawnT: 1.8, shield: 0 });
    R.explode(this.parts, p.x, p.y, 2.6);
    this.shake = 12; this.flash = 0.5; this.eb = [];
    audio.die();
  }

  private gameOver() {
    const rec = this.score > this.hi;
    this.mode = 'over';
    if (rec) {
      this.hi = this.score;
      try { localStorage.setItem(HI_KEY, String(this.hi)); } catch { /* sin almacenamiento */ }
    }
    this.cb.onHud(this.hud());
    this.cb.onEnd({
      score: this.score, hi: this.hi, newRecord: rec && this.score > 0, level: this.level, kills: this.kills,
      accuracy: this.shots ? Math.min(100, Math.round((this.hits / this.shots) * 100)) : 0,
    });
  }

  hud(): HudState {
    const p = this.p, boss = this.boss;
    return {
      score: this.score, hi: Math.max(this.hi, this.score), lives: p.lives, bombs: p.bombs, loops: p.loops,
      power: p.power, shield: p.shield, level: this.level, levelName: this.world.pal.name,
      progress: this.phase === 'waves' ? Math.min(1, this.levelT / LEVEL_LEN) : 1,
      boss: boss && boss.b ? Math.max(0, boss.hp / boss.maxHp) : null,
      banner: this.banner,
    };
  }

  private draw() {
    const c = this.b, S = getSprites(), t = this.time;
    c.imageSmoothingEnabled = false;
    this.world.drawSea(c, this.W, this.H, t);
    for (const e of this.enemies) if (e.ground) R.drawEnemy(c, e, S, t);
    R.drawShadows(c, this.enemies, this.p, S, this.mode !== 'over');
    R.drawPowerups(c, this.pups, S, t);
    for (const e of this.enemies) if (e.kind === 'boss') R.drawEnemy(c, e, S, t);
    for (const e of this.enemies) if (!e.ground && e.kind !== 'boss') R.drawEnemy(c, e, S, t);
    R.drawPlayerBullets(c, this.pb);
    if (this.mode !== 'over') R.drawPlayer(c, this.p, S, t);
    R.drawParticles(c, this.parts);
    this.world.drawClouds(c);
    R.drawEnemyBullets(c, this.eb, t);
    // composición en pantalla: escalado entero, sacudida, scanlines, viñeta y destello
    const s = this.sctx, k = this.k, cw = this.cv.width, ch = this.cv.height;
    let ox = 0, oy = 0;
    s.setTransform(1, 0, 0, 1, 0, 0);
    s.imageSmoothingEnabled = false;
    if (this.shake > 0.3 && !this.paused) {
      ox = Math.round((Math.random() - 0.5) * this.shake) * k;
      oy = Math.round((Math.random() - 0.5) * this.shake) * k;
      s.fillStyle = '#06101e';
      s.fillRect(0, 0, cw, ch);
    }
    s.drawImage(this.buf, ox, oy, this.W * k, this.H * k);
    if (this.scan && k >= 2) { s.fillStyle = this.scan; s.fillRect(0, 0, cw, ch); }
    if (this.vignette) { s.fillStyle = this.vignette; s.fillRect(0, 0, cw, ch); }
    if (this.flash > 0) { s.fillStyle = `rgba(255,250,235,${Math.min(0.85, this.flash)})`; s.fillRect(0, 0, cw, ch); }
  }
}

// Tipos y datos compartidos del juego.

export type EnemyKind = 'zero' | 'red' | 'mini' | 'bomber' | 'boat' | 'boss';
export type Move = 'dive' | 'swoop' | 'loop' | 'chase' | 'drift' | 'boat' | 'boss';
export type PUType = 'P' | 'S' | 'B' | '1';

export interface Enemy {
  kind: EnemyKind; mode: Move;
  x: number; y: number; vx: number; vy: number; t: number;
  hp: number; maxHp: number; r: number; score: number;
  fireT: number; flash: number;
  a: number; b: number; c: number; d: number; dir: number;
  group: number; dead: boolean; ground: boolean; aim: number; variant: number;
}

export interface Bullet { x: number; y: number; vx: number; vy: number; r: number; life: number; }

export interface Particle {
  x: number; y: number; vx: number; vy: number;
  life: number; max: number; size: number; color: string;
  kind: 0 | 1 | 2 | 3 | 4; // chispa, humo, onda, destello, texto
  text?: string;
}

export interface PowerUp { x: number; y: number; t: number; type: PUType; taken: boolean; }

export interface Player {
  x: number; y: number; alive: boolean;
  lives: number; bombs: number; loops: number; power: number;
  shield: number; inv: number; loopT: number; fireT: number; respawnT: number; tilt: number;
}

export interface HudState {
  score: number; hi: number; lives: number; bombs: number; loops: number; power: number;
  shield: number; level: number; levelName: string; progress: number;
  boss: number | null; banner: { title: string; sub: string } | null;
}

export interface EndStats { score: number; hi: number; newRecord: boolean; level: number; kills: number; accuracy: number; }

export const LOOP_T = 1.1;

export const STATS: Record<EnemyKind, { hp: number; r: number; score: number; fire: number }> = {
  zero: { hp: 1, r: 7, score: 100, fire: 2.6 },
  red: { hp: 2, r: 7, score: 250, fire: 1.8 },
  mini: { hp: 1, r: 6, score: 80, fire: 2.0 },
  bomber: { hp: 14, r: 13, score: 1200, fire: 1.5 },
  boat: { hp: 6, r: 9, score: 600, fire: 1.7 },
  boss: { hp: 230, r: 26, score: 20000, fire: 1 },
};

export const DIFFS = {
  facil: { label: 'Recluta', desc: '4 vidas · balas lentas', lives: 4, bspd: 0.8, fire: 0.7, hp: 0.8 },
  normal: { label: 'Piloto', desc: '3 vidas · equilibrado', lives: 3, bspd: 1, fire: 1, hp: 1 },
  dificil: { label: 'As del aire', desc: '2 vidas · lluvia de balas', lives: 2, bspd: 1.2, fire: 1.4, hp: 1.3 },
};
export type DiffKey = keyof typeof DIFFS;
export type Diff = (typeof DIFFS)[DiffKey];

export function makeEnemy(kind: EnemyKind, x: number, y: number, mode: Move, o: Partial<Enemy> = {}): Enemy {
  const s = STATS[kind];
  const e: Enemy = {
    kind, mode, x, y, vx: 0, vy: 50, t: 0, hp: s.hp, maxHp: s.hp, r: s.r, score: s.score,
    fireT: s.fire * (0.2 + Math.random() * 0.8), flash: 0, a: 0, b: 0, c: 0, d: 0, dir: 1,
    group: 0, dead: false, ground: kind === 'boat', aim: Math.PI / 2, variant: 0, ...o,
  };
  e.maxHp = e.hp;
  return e;
}

export const clamp = (v: number, a: number, b: number) => (v < a ? a : v > b ? b : v);

// Entrada de teclado (en window) + joystick/botones táctiles.

const BLOCK = new Set(['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space']);
const LOOP_KEYS = new Set(['Space', 'ShiftLeft', 'ShiftRight', 'KeyK']);
const BOMB_KEYS = new Set(['KeyX', 'KeyB', 'KeyJ']);

export class Input {
  keys = new Set<string>();
  joy = { x: 0, y: 0 };
  private loopReq = false;
  private bombReq = false;

  private onDown = (e: KeyboardEvent) => {
    if (BLOCK.has(e.code)) e.preventDefault();
    if (!e.repeat) {
      if (LOOP_KEYS.has(e.code)) this.loopReq = true;
      if (BOMB_KEYS.has(e.code)) this.bombReq = true;
    }
    this.keys.add(e.code);
  };
  private onUp = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private onBlur = () => { this.keys.clear(); };

  attach() {
    window.addEventListener('keydown', this.onDown);
    window.addEventListener('keyup', this.onUp);
    window.addEventListener('blur', this.onBlur);
  }

  detach() {
    window.removeEventListener('keydown', this.onDown);
    window.removeEventListener('keyup', this.onUp);
    window.removeEventListener('blur', this.onBlur);
  }

  requestLoop() { this.loopReq = true; }
  requestBomb() { this.bombReq = true; }

  consumeLoop() { const r = this.loopReq; this.loopReq = false; return r; }
  consumeBomb() { const r = this.bombReq; this.bombReq = false; return r; }

  axis() {
    const k = this.keys;
    let x = this.joy.x, y = this.joy.y;
    if (k.has('ArrowLeft') || k.has('KeyA')) x -= 1;
    if (k.has('ArrowRight') || k.has('KeyD')) x += 1;
    if (k.has('ArrowUp') || k.has('KeyW')) y -= 1;
    if (k.has('ArrowDown') || k.has('KeyS')) y += 1;
    const m = Math.hypot(x, y);
    if (m > 1) { x /= m; y /= m; }
    return { x, y };
  }
}

// Dibujo de entidades y sistema de partículas (efectos).
import { LOOP_T } from './entities';
import type { Bullet, Enemy, Particle, Player, PowerUp } from './entities';
import type { Sprite, SpriteSet } from './sprites';

const MAX_PARTS = 700;
const FIRE = ['#fff6c0', '#ffd23c', '#ff8a1e', '#e8402a'];

function push(parts: Particle[], p: Particle) {
  if (parts.length < MAX_PARTS) parts.push(p);
}

export function explode(parts: Particle[], x: number, y: number, s: number) {
  push(parts, { x, y, vx: 0, vy: 0, life: 0.18 + 0.06 * s, max: 0.18 + 0.06 * s, size: 6 * s, color: '#fff3b0', kind: 3 });
  push(parts, { x, y, vx: 0, vy: 0, life: 0.4, max: 0.4, size: 12 * s, color: '#ffe8a0', kind: 2 });
  for (let i = 0; i < Math.round(12 * s); i++) {
    const a = Math.random() * Math.PI * 2, v = (30 + Math.random() * 90) * Math.sqrt(s), l = 0.3 + Math.random() * 0.45;
    push(parts, { x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life: l, max: l, size: Math.random() < 0.3 ? 2 : 1, color: FIRE[i % 4], kind: 0 });
  }
  for (let i = 0; i < Math.round(5 * s); i++) {
    const l = 0.8 + Math.random() * 0.7, j = () => (Math.random() - 0.5) * 8 * s;
    push(parts, { x: x + j(), y: y + j(), vx: j() * 2, vy: 10 + Math.random() * 20, life: l, max: l, size: (2 + Math.random() * 3) * Math.sqrt(s), color: i % 2 ? '#55555f' : '#7a7a84', kind: 1 });
  }
}

export function sparks(parts: Particle[], x: number, y: number, n: number, color: string) {
  for (let i = 0; i < n; i++) {
    const a = Math.random() * Math.PI * 2, v = 30 + Math.random() * 60;
    push(parts, { x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v, life: 0.25, max: 0.25, size: 1, color, kind: 0 });
  }
}

export function ring(parts: Particle[], x: number, y: number, size: number, color: string, life = 0.5) {
  push(parts, { x, y, vx: 0, vy: 0, life, max: life, size, color, kind: 2 });
}

export function floatText(parts: Particle[], x: number, y: number, text: string, color = '#ffffff') {
  parts.push({ x, y, vx: 0, vy: -18, life: 1.1, max: 1.1, size: 8, color, kind: 4, text });
}

export function updateParticles(parts: Particle[], dt: number): Particle[] {
  for (const p of parts) {
    p.life -= dt; p.x += p.vx * dt; p.y += p.vy * dt;
    if (p.kind === 0) { p.vx *= 0.94; p.vy *= 0.94; }
  }
  return parts.filter(p => p.life > 0);
}

const circle = (c: CanvasRenderingContext2D, x: number, y: number, r: number) => { c.beginPath(); c.arc(x, y, Math.max(0.5, r), 0, Math.PI * 2); };

export function drawParticles(c: CanvasRenderingContext2D, parts: Particle[]) {
  for (const p of parts) {
    if (p.kind !== 1) continue;
    c.globalAlpha = (p.life / p.max) * 0.55; c.fillStyle = p.color;
    circle(c, p.x, p.y, p.size * (1.6 - (p.life / p.max) * 0.6)); c.fill();
  }
  c.globalCompositeOperation = 'lighter';
  for (const p of parts) {
    const k = p.life / p.max;
    c.globalAlpha = p.kind === 0 ? Math.min(1, k * 1.5) : k;
    if (p.kind === 0) { c.fillStyle = p.color; c.fillRect(Math.round(p.x), Math.round(p.y), p.size, p.size); }
    else if (p.kind === 2) { c.strokeStyle = p.color; c.lineWidth = 2; circle(c, p.x, p.y, p.size * (1 - k) + 1); c.stroke(); }
    else if (p.kind === 3) {
      c.fillStyle = '#ff9a3c'; circle(c, p.x, p.y, p.size * (0.6 + k)); c.fill();
      c.fillStyle = p.color; circle(c, p.x, p.y, p.size * k); c.fill();
    }
  }
  c.globalCompositeOperation = 'source-over';
  c.font = 'bold 8px monospace'; c.textAlign = 'center'; c.lineWidth = 2; c.strokeStyle = '#141423';
  for (const p of parts) {
    if (p.kind !== 4 || !p.text) continue;
    c.globalAlpha = Math.min(1, (p.life / p.max) * 2); c.fillStyle = p.color;
    c.strokeText(p.text, Math.round(p.x), Math.round(p.y)); c.fillText(p.text, Math.round(p.x), Math.round(p.y));
  }
  c.globalAlpha = 1;
}

function sprOf(e: Enemy, S: SpriteSet): Sprite {
  return e.kind === 'boss' ? S.bosses[e.variant % S.bosses.length] : S[e.kind];
}

const ROTATES = new Set(['zero', 'red', 'mini']);

export function drawShadows(c: CanvasRenderingContext2D, enemies: Enemy[], p: Player, S: SpriteSet, showPlayer: boolean) {
  c.globalAlpha = 0.28;
  for (const e of enemies) {
    if (e.t < 0 || e.ground) continue;
    const s = sprOf(e, S), off = e.kind === 'boss' ? 22 : e.kind === 'bomber' ? 16 : 11;
    c.drawImage(s.shadow, Math.round(e.x - s.w / 2 + off * 0.7), Math.round(e.y - s.h / 2 + off));
  }
  if (showPlayer && p.alive) {
    const ph = p.loopT > 0 ? 1 - p.loopT / LOOP_T : 0, lift = 12 + Math.sin(ph * Math.PI) * 18, s = S.player;
    c.drawImage(s.shadow, Math.round(p.x - s.w / 2 + lift * 0.7), Math.round(p.y - s.h / 2 + lift));
  }
  c.globalAlpha = 1;
}

export function drawEnemy(c: CanvasRenderingContext2D, e: Enemy, S: SpriteSet, time: number) {
  if (e.t < 0) return;
  const s = sprOf(e, S);
  const img = e.flash > 0 ? s.white : s.img;
  const x = Math.round(e.x), y = Math.round(e.y);
  if (e.kind === 'boat') {
    c.fillStyle = 'rgba(255,255,255,0.55)';
    for (let i = 0; i < 6; i++) c.fillRect(x - 3 - i, y + 9 + i * 2, 2, 1), c.fillRect(x + 2 + i, y + 9 + i * 2, 2, 1);
    c.drawImage(img, x - s.w / 2, y - s.h / 2);
    c.strokeStyle = '#3c4250'; c.lineWidth = 1; c.fillStyle = '#141423';
    for (const oy of [-4, 5]) {
      c.fillRect(x - 2, y + oy - 2, 4, 4);
      c.beginPath(); c.moveTo(x, y + oy); c.lineTo(x + Math.cos(e.aim) * 6, y + oy + Math.sin(e.aim) * 6); c.stroke();
    }
    return;
  }
  if (ROTATES.has(e.kind)) {
    c.save();
    c.translate(x, y);
    c.rotate(e.aim - Math.PI / 2);
    c.drawImage(img, -s.w / 2, -s.h / 2);
    c.restore();
  } else {
    c.drawImage(img, x - s.w / 2, y - s.h / 2);
  }
  if (e.kind === 'bomber' || e.kind === 'boss') {
    const f = Math.floor(time * 40) % 2, boss = e.kind === 'boss';
    c.fillStyle = 'rgba(230,230,230,0.7)';
    for (const px of boss ? [-22, -12, 12, 22] : [-3, 3]) c.fillRect(x + px - 3 - f, y + (boss ? 5 : 4), 6 + f * 2, 1);
  }
  if (e.kind === 'boss' && e.hp < e.maxHp * 0.5 && Math.random() < 0.5) {
    c.fillStyle = Math.random() < 0.5 ? '#ff8a1e' : '#ffd23c';
    c.fillRect(x - 22 + Math.floor(Math.random() * 3), y - 2, 2, 2);
  }
}

export function drawPlayer(c: CanvasRenderingContext2D, p: Player, S: SpriteSet, time: number) {
  if (!p.alive) return;
  if (p.inv > 0 && p.loopT <= 0 && Math.floor(time * 16) % 2 === 0) return;
  const s = S.player;
  const ph = p.loopT > 0 ? 1 - p.loopT / LOOP_T : 0;
  const sc = 1 + 0.55 * Math.sin(ph * Math.PI);
  const sy = Math.cos(ph * Math.PI * 2);
  const sx = 1 - Math.abs(p.tilt) * 0.22;
  c.save();
  c.translate(Math.round(p.x), Math.round(p.y));
  c.scale(sx * sc, sy * sc);
  c.drawImage(sy < 0 ? s.shadow : s.img, -s.w / 2, -s.h / 2);
  if (sy < 0) { c.globalAlpha = 0.6; c.drawImage(s.img, -s.w / 2, -s.h / 2); c.globalAlpha = 1; }
  const f = Math.floor(time * 30) % 2;
  c.fillStyle = 'rgba(235,235,235,0.85)';
  for (const bx of [-5.5, 5.5]) c.fillRect(bx - 2 - f, -6, 4 + f * 2, 1);
  if (p.fireT > 0.06 && p.loopT <= 0) {
    c.fillStyle = '#fff6a0';
    c.fillRect(-2, -10, 1, 2); c.fillRect(1, -10, 1, 2);
  }
  c.restore();
  if (p.shield > 0 && (p.shield > 2 || Math.floor(time * 10) % 2 === 0)) {
    c.globalCompositeOperation = 'lighter';
    c.strokeStyle = `rgba(110,230,255,${0.55 + 0.3 * Math.sin(time * 12)})`;
    c.lineWidth = 1;
    c.beginPath(); c.arc(Math.round(p.x), Math.round(p.y), 12 + Math.sin(time * 8), 0, Math.PI * 2); c.stroke();
    c.fillStyle = 'rgba(80,200,255,0.12)';
    c.fill();
    c.globalCompositeOperation = 'source-over';
  }
}

export function drawPlayerBullets(c: CanvasRenderingContext2D, pb: Bullet[]) {
  for (const b of pb) {
    const x = Math.round(b.x), y = Math.round(b.y);
    c.fillStyle = '#ffb81e';
    c.fillRect(x - 1, y - 2, 2, 6);
    c.fillStyle = '#fffbe0';
    c.fillRect(x - 1, y - 3, 2, 3);
  }
}

export function drawEnemyBullets(c: CanvasRenderingContext2D, eb: Bullet[], time: number) {
  const outer = Math.floor(time * 12) % 2 ? '#ff3c78' : '#ff9a3c';
  c.globalCompositeOperation = 'lighter';
  c.fillStyle = 'rgba(255,80,120,0.28)';
  for (const b of eb) c.fillRect(Math.round(b.x) - b.r - 1, Math.round(b.y) - b.r - 1, b.r * 2 + 2, b.r * 2 + 2);
  c.globalCompositeOperation = 'source-over';
  for (const b of eb) {
    const x = Math.round(b.x), y = Math.round(b.y), r = b.r;
    c.fillStyle = outer;
    c.fillRect(x - r, y - r + 1, r * 2, r * 2 - 2);
    c.fillRect(x - r + 1, y - r, r * 2 - 2, r * 2);
    c.fillStyle = '#ffffff';
    c.fillRect(x - 1, y - 1, 2, 2);
  }
}

export function drawPowerups(c: CanvasRenderingContext2D, pups: PowerUp[], S: SpriteSet, time: number) {
  for (const u of pups) {
    const s = S.pups[u.type];
    const img = Math.floor(time * 5) % 4 === 0 ? s.white : s.img;
    c.globalCompositeOperation = 'lighter';
    c.fillStyle = 'rgba(255,255,200,0.15)';
    c.beginPath(); c.arc(u.x, u.y, 9 + Math.sin(time * 8) * 1.5, 0, Math.PI * 2); c.fill();
    c.globalCompositeOperation = 'source-over';
    c.drawImage(img, Math.round(u.x - s.w / 2), Math.round(u.y - s.h / 2));
  }
}

// Pixel art dibujado por código: mapas de caracteres (mitad izquierda, se reflejan) → canvas.

export interface Sprite {
  img: HTMLCanvasElement;
  white: HTMLCanvasElement;
  shadow: HTMLCanvasElement;
  w: number;
  h: number;
}

export interface SpriteSet {
  player: Sprite;
  zero: Sprite;
  red: Sprite;
  mini: Sprite;
  bomber: Sprite;
  boat: Sprite;
  bosses: Sprite[];
  pups: Record<string, Sprite>;
}

export const PAL: Record<string, string> = {
  k: '#141423', w: '#f4f4f4', g: '#b8c0cc', G: '#7a8494', d: '#3c4250',
  r: '#d8343c', R: '#8c1c28', y: '#ffd23c', o: '#ff8a1e',
  b: '#5aa0e6', B: '#2d5aa0', n: '#7cbc5a', N: '#3f7a3c',
  c: '#8ef0ff', t: '#c8a868', T: '#8a7040',
};

export function makeCanvas(w: number, h: number): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = Math.max(1, w);
  c.height = Math.max(1, h);
  return c;
}

export function tint(src: HTMLCanvasElement, color: string): HTMLCanvasElement {
  const c = makeCanvas(src.width, src.height);
  const x = c.getContext('2d')!;
  x.drawImage(src, 0, 0);
  x.globalCompositeOperation = 'source-in';
  x.fillStyle = color;
  x.fillRect(0, 0, c.width, c.height);
  return c;
}

function finish(img: HTMLCanvasElement): Sprite {
  return { img, white: tint(img, '#ffffff'), shadow: tint(img, '#000000'), w: img.width, h: img.height };
}

const mirror = (rows: string[]) => rows.map(r => r + r.split('').reverse().join(''));

function fromRows(rows: string[], over: Record<string, string> = {}): Sprite {
  const h = rows.length;
  const w = Math.max(...rows.map(r => r.length));
  const c = makeCanvas(w, h);
  const x = c.getContext('2d')!;
  rows.forEach((row, y) => {
    for (let i = 0; i < row.length; i++) {
      const ch = row[i];
      if (ch === '.') continue;
      x.fillStyle = over[ch] ?? PAL[ch] ?? '#ff00ff';
      x.fillRect(i, y, 1, 1);
    }
  });
  return finish(c);
}

// Caza bimotor del jugador (mira hacia arriba)
const PLAYER = [
  '.......k', '......kc', '......kc', '..k...kb', '.kgk..kb', '.kgk..kb', 'kkgkkkkb', 'kbbbbbbb',
  'kBwbbbbb', 'kkkgkkkb', '..kgk.kb', '..kgk..k', '..kgk...', '.kkgkkkk', '.kBBBBBB', '.kkkkkkk',
];
// Caza enemigo (mira hacia abajo)
const ZERO = [
  '....kkk', '...kNNN', '.kkkNNN', '....kNN', '.....kN', 'kkkkkkN', 'kNNNNNN',
  'kNNrNNN', 'kNrrrNN', 'kNNrNNN', '.kkkkkN', '.....kc', '....kdd', '.....kg',
];
// Bombardero bimotor
const BOMBER = [
  '..........kk', '.........kTT', '.....kkkkkTT', '.....kTTTTTT', '......kkkkTT', '..........kT',
  'kkkkkkkkkkkT', 'kttttttttttT', 'kttttrttkdtT', 'ktttrrrtkdtT', 'kttttrttkdtT', '.kkkkkkkkdkT',
  '........kgkt', '..........kc', '..........kc', '...........k',
];
// Cañonera (proa arriba)
const BOAT = [
  '.....k', '....kG', '....kg', '...kGg', '...kgg', '..kGgt', '..kgtt', '..kgtt', '..kgdd', '..kgdw',
  '..kgdd', '..kgdd', '..kgtt', '..kgtt', '..kgtt', '..kgtt', '..kGgg', '...kGG', '...kkk',
];

function bossCanvas(main: string, dark: string, light: string): HTMLCanvasElement {
  const c = makeCanvas(64, 40);
  const x = c.getContext('2d')!;
  const R = (col: string, a: number, b: number, w: number, h: number) => { x.fillStyle = col; x.fillRect(a, b, w, h); };
  for (let pass = 0; pass < 2; pass++) {
    const o = pass === 0 ? 1 : 0;
    const col = pass === 0 ? PAL.k : main;
    R(col, 18 - o, 2 - o, 28 + 2 * o, 5 + 2 * o);
    R(col, 28 - o, 0 - o, 8 + 2 * o, 38 + 2 * o);
    for (let y = 11; y <= 21; y++) {
      const half = Math.round(31 - Math.abs(y - 15) * 1.6);
      R(col, 32 - half - o, y - o, half * 2 + 2 * o, 1 + 2 * o);
    }
  }
  R(light, 2, 12, 60, 1);
  R(dark, 4, 18, 56, 1);
  R(light, 20, 3, 24, 1);
  for (const ex of [-22, -12, 12, 22]) {
    R(PAL.k, 32 + ex - 3, 8, 6, 17);
    R(dark, 32 + ex - 2, 9, 4, 15);
    R(light, 32 + ex - 2, 9, 1, 14);
    R('#d0d0d0', 32 + ex - 4, 25, 8, 1);
  }
  R(light, 30, 2, 1, 34);
  R(dark, 34, 2, 1, 34);
  R('#8ef0ff', 30, 33, 4, 4);
  R('#ffffff', 30, 33, 1, 1);
  for (const s of [-1, 1]) {
    R('#f4f4f4', 32 + s * 27 - 2, 13, 4, 4);
    R('#d8343c', 32 + s * 27 - 1, 14, 2, 2);
  }
  R(PAL.k, 30, 17, 4, 4);
  R('#ffd23c', 31, 18, 2, 2);
  return c;
}

const GLYPH: Record<string, string[]> = {
  P: ['111', '101', '111', '100', '100'],
  S: ['111', '100', '111', '001', '111'],
  B: ['110', '101', '110', '101', '110'],
  '1': ['010', '110', '010', '010', '111'],
};
export const PUP_COLORS: Record<string, string> = { P: '#e83c3c', S: '#2ec4e8', B: '#ff9a1e', '1': '#3cc864' };

function pupCanvas(type: string): HTMLCanvasElement {
  const c = makeCanvas(13, 13);
  const x = c.getContext('2d')!;
  const col = PUP_COLORS[type];
  for (let yy = 0; yy < 13; yy++) {
    for (let xx = 0; xx < 13; xx++) {
      const d = Math.hypot(xx + 0.5 - 6.5, yy + 0.5 - 6.5);
      if (d > 6.4) continue;
      x.fillStyle = d > 5.4 ? PAL.k : yy < 5 && d < 4.5 ? '#ffffff55' : col;
      x.fillRect(xx, yy, 1, 1);
      if (yy < 5 && d < 4.5) { x.fillStyle = col; x.globalAlpha = 0.65; x.fillRect(xx, yy, 1, 1); x.globalAlpha = 1; }
    }
  }
  for (const [col, o] of [[PAL.k, 1], ['#ffffff', 0]] as [string, number][]) {
    x.fillStyle = col;
    GLYPH[type].forEach((row, gy) => { for (let gx = 0; gx < 3; gx++) if (row[gx] === '1') x.fillRect(5 + gx + o, 4 + gy + o, 1, 1); });
  }
  return c;
}

let cache: SpriteSet | null = null;

export function getSprites(): SpriteSet {
  if (cache) return cache;
  const bossCols: [string, string, string][] = [
    ['#6a7a4a', '#3a4a28', '#9aaa70'],
    ['#5a6a8a', '#2a3450', '#90a0c0'],
    ['#8a2a2a', '#4a1010', '#c06060'],
    ['#3a3a44', '#18181e', '#707080'],
  ];
  const pups: Record<string, Sprite> = {};
  for (const k of Object.keys(GLYPH)) pups[k] = finish(pupCanvas(k));
  cache = {
    player: fromRows(mirror(PLAYER)),
    zero: fromRows(mirror(ZERO)),
    red: fromRows(mirror(ZERO), { N: '#d03030', r: '#ffe060' }),
    mini: fromRows(mirror(ZERO), { N: '#7a8494', r: '#d8343c' }),
    bomber: fromRows(mirror(BOMBER)),
    boat: fromRows(mirror(BOAT)),
    bosses: bossCols.map(([m, d, l]) => finish(bossCanvas(m, d, l))),
    pups,
  };
  return cache;
}

// Generador de oleadas con patrones de vuelo.
import { makeEnemy } from './entities';
import type { Enemy } from './entities';

export type WaveType = 'line' | 'vee' | 'swoop' | 'loopers' | 'red' | 'bomber' | 'boats' | 'chasers';

export interface WaveCtx {
  W: number; H: number; level: number;
  add: (e: Enemy) => void;
  newGroup: (n: number) => number;
}

const OPENING: WaveType[] = ['swoop', 'line', 'bomber', 'red', 'boats'];

export function pickWave(level: number, n: number): WaveType {
  if (n < OPENING.length && level === 1) return OPENING[n];
  const table: [WaveType, number][] = [
    ['line', 3], ['vee', 2.4], ['swoop', 3], ['loopers', 2], ['red', 1.4],
    ['bomber', level >= 2 ? 1.6 : 0.8], ['boats', 1.2], ['chasers', level >= 2 ? 1.6 : 0.5],
  ];
  const total = table.reduce((s, [, w]) => s + w, 0);
  let r = Math.random() * total;
  for (const [t, w] of table) { r -= w; if (r <= 0) return t; }
  return 'line';
}

function swoopWave(c: WaveCtx, kind: 'zero' | 'red', n: number, group = 0) {
  const side = Math.random() < 0.5 ? 1 : -1;
  const y0 = 8 + Math.random() * c.H * 0.14;
  for (let i = 0; i < n; i++) {
    const x0 = side > 0 ? -10 : c.W + 10;
    c.add(makeEnemy(kind, x0, y0, 'swoop', { a: x0, b: y0, dir: side, c: c.W / 2.3, t: -i * 0.2, group }));
  }
}

export function spawnWave(type: WaveType, c: WaveCtx) {
  const { W, H, level } = c;
  const hpBoost = level >= 3 ? 1 : 0;
  switch (type) {
    case 'line': {
      const n = 5 + Math.min(3, level - 1);
      const amp = 10 + Math.random() * 16, ph = Math.random() * 6;
      for (let i = 0; i < n; i++) {
        const x = ((i + 1) * W) / (n + 1);
        c.add(makeEnemy('zero', x, -12, 'dive', { a: x, b: amp, c: ph + i * 0.5, vy: 50 + level * 4, t: -i * 0.12, hp: 1 + hpBoost }));
      }
      break;
    }
    case 'vee': {
      const cx = W * (0.25 + Math.random() * 0.5);
      for (let i = -3; i <= 3; i++) {
        const x = cx + i * 16;
        c.add(makeEnemy('zero', x, -12, 'dive', { a: x, vy: 70 + level * 3, d: 1, dir: i < 0 ? -1 : 1, t: -Math.abs(i) * 0.18, hp: 1 + hpBoost }));
      }
      break;
    }
    case 'swoop':
      swoopWave(c, 'zero', 6);
      break;
    case 'red':
      swoopWave(c, 'red', 5, c.newGroup(5));
      break;
    case 'loopers': {
      const n = 4;
      for (let i = 0; i < n; i++) {
        const x = W * (0.2 + (0.6 * i) / (n - 1));
        c.add(makeEnemy('zero', x, -12, 'loop', { a: H * (0.28 + Math.random() * 0.15), dir: x < W / 2 ? 1 : -1, vy: 85, t: -i * 0.3, hp: 1 + hpBoost }));
      }
      break;
    }
    case 'bomber': {
      const n = level >= 3 ? 2 : 1;
      for (let i = 0; i < n; i++) {
        const x = n === 1 ? W * (0.3 + Math.random() * 0.4) : W * (0.3 + i * 0.4);
        c.add(makeEnemy('bomber', x, -20, 'drift', { vy: 20, hp: 14 + level * 3, t: -i * 0.8 }));
      }
      break;
    }
    case 'boats': {
      const n = 2 + (level > 2 ? 1 : 0);
      for (let i = 0; i < n; i++) {
        c.add(makeEnemy('boat', W * (0.12 + 0.76 * Math.random()), -20 - i * 46, 'boat', { vx: (Math.random() - 0.5) * 10, hp: 6 + level }));
      }
      break;
    }
    case 'chasers': {
      const n = 3 + Math.min(2, level - 1);
      for (let i = 0; i < n; i++) {
        c.add(makeEnemy('mini', W * (0.15 + 0.7 * Math.random()), -12, 'chase', { vy: 75 + level * 4, t: -i * 0.35 }));
      }
      break;
    }
  }
}

// Fondo: océano en mosaico pixel art, islas procedurales, destellos y nubes.
import { makeCanvas, tint } from './sprites';

export interface Palette {
  name: string;
  deep: string; mid: string; crest: string; shallow: string;
  sand: string; sand2: string; jungle: string; jungleDark: string; hill: string;
  tint: string;
}

export const PALETTES: Palette[] = [
  { name: 'Mar del Coral', deep: '#1a5aa6', mid: '#226cba', crest: '#a6dcf8', shallow: '#3fb8c8', sand: '#ecd89c', sand2: '#cdb478', jungle: '#3f9a3a', jungleDark: '#24622a', hill: '#68b84c', tint: '' },
  { name: 'Atardecer en Midway', deep: '#2b3f86', mid: '#36508f', crest: '#ffb38a', shallow: '#4a8fb0', sand: '#f0c890', sand2: '#d0a070', jungle: '#4a7a34', jungleDark: '#2c4c22', hill: '#7a9a40', tint: 'rgba(255,110,50,0.10)' },
  { name: 'Tormenta Nocturna', deep: '#0e2440', mid: '#15314f', crest: '#7a9ac0', shallow: '#24506a', sand: '#a09878', sand2: '#80785c', jungle: '#24503a', jungleDark: '#143022', hill: '#346048', tint: 'rgba(10,20,70,0.22)' },
  { name: 'Arrecife de Leyte', deep: '#0d6c86', mid: '#11809a', crest: '#c0f6f0', shallow: '#40d0c8', sand: '#f4e4b0', sand2: '#d8c488', jungle: '#2f9a4a', jungleDark: '#1c6a32', hill: '#5cc060', tint: '' },
];

export function hash(a: number, b: number, s: number): number {
  let h = Math.imul(a | 0, 374761393) ^ Math.imul(b | 0, 668265263) ^ Math.imul(s | 0, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

function rgb(hex: string): number[] {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function oceanTile(p: Palette): HTMLCanvasElement {
  const S = 64;
  const c = makeCanvas(S, S);
  const x = c.getContext('2d')!;
  const img = x.createImageData(S, S);
  const deep = rgb(p.deep), mid = rgb(p.mid), crest = rgb(p.crest);
  const put = (px: number, py: number, col: number[]) => {
    img.data.set([col[0], col[1], col[2], 255], (((py + S) % S) * S + ((px + S) % S)) * 4);
  };
  for (let yy = 0; yy < S; yy++) {
    for (let xx = 0; xx < S; xx++) {
      const v = Math.sin((xx / S) * Math.PI * 4 + Math.sin((yy / S) * Math.PI * 2) * 1.6) * 0.5 + 0.5;
      put(xx, yy, v * 0.45 + hash(xx, yy, 1) * 0.6 > 0.74 ? mid : deep);
    }
  }
  for (let k = 0; k < 16; k++) {
    const cx = Math.floor(hash(k, 0, 7) * S), cy = Math.floor(hash(k, 1, 7) * S);
    const len = 3 + Math.floor(hash(k, 2, 7) * 5);
    for (let i = 0; i < len; i++) put(cx + i, cy, crest);
    for (let i = 1; i < len + 1; i++) put(cx + i, cy + 1, mid);
  }
  x.putImageData(img, 0, 0);
  return c;
}

function makeIsland(p: Palette, seed: number): HTMLCanvasElement {
  const rw = 22 + Math.floor(hash(seed, 1, 9) * 40), rh = 18 + Math.floor(hash(seed, 2, 9) * 32);
  const w = rw * 2 + 12, h = rh * 2 + 12, cx = w / 2, cy = h / 2;
  const ph = [hash(seed, 3, 9) * 6.28, hash(seed, 4, 9) * 6.28, hash(seed, 5, 9) * 6.28];
  const hx = (hash(seed, 6, 9) - 0.5) * rw * 0.6, hy = (hash(seed, 7, 9) - 0.5) * rh * 0.6;
  const c = makeCanvas(w, h);
  const ctx = c.getContext('2d')!;
  const img = ctx.createImageData(w, h);
  const C = { sh: rgb(p.shallow), sa: rgb(p.sand), s2: rgb(p.sand2), j: rgb(p.jungle), jd: rgb(p.jungleDark), hi: rgb(p.hill) };
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const dx = (x - cx) / rw, dy = (y - cy) / rh, a = Math.atan2(dy, dx);
      const n = hash(x, y, seed);
      const rr = 1 + 0.18 * Math.sin(3 * a + ph[0]) + 0.1 * Math.sin(5 * a + ph[1]) + 0.05 * Math.sin(9 * a + ph[2]);
      const dist = Math.sqrt(dx * dx + dy * dy) / rr + (n - 0.5) * 0.06;
      let col: number[] | null = null, al = 255;
      if (dist < 0.68) {
        const hd = Math.hypot((x - cx - hx) / rw, (y - cy - hy) / rh);
        col = n < 0.14 ? C.jd : hd < 0.3 + n * 0.06 ? C.hi : C.j;
      } else if (dist < 0.84) col = n < 0.18 ? C.s2 : C.sa;
      else if (dist < 1.0) { col = C.sh; al = 200; }
      else if (dist < 1.12 && n < 0.55) { col = C.sh; al = 110; }
      if (col) img.data.set([col[0], col[1], col[2], al], (y * w + x) * 4);
    }
  }
  ctx.putImageData(img, 0, 0);
  return c;
}

function makeCloud(seed: number): HTMLCanvasElement {
  const w = 56 + Math.floor(hash(seed, 1, 5) * 54), h = 30 + Math.floor(hash(seed, 2, 5) * 16);
  const n = 5 + Math.floor(hash(seed, 3, 5) * 4);
  const blobs: number[][] = [];
  for (let i = 0; i < n; i++) {
    blobs.push([w * (0.2 + 0.6 * hash(seed, i, 11)), h * (0.42 + 0.2 * hash(seed, i, 12)), h * (0.2 + 0.2 * hash(seed, i, 13))]);
  }
  const inside = (x: number, y: number) => blobs.some(([bx, by, br]) => (x - bx) ** 2 + (y - by) ** 2 < br * br);
  const c = makeCanvas(w, h);
  const ctx = c.getContext('2d')!;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (!inside(x, y)) continue;
      ctx.fillStyle = !inside(x, y + 3) ? '#aebdd2' : !inside(x, y - 2) ? '#ffffff' : '#e6edf6';
      ctx.fillRect(x, y, 1, 1);
    }
  }
  return c;
}

interface Isle { img: HTMLCanvasElement; x: number; y: number; }
interface Cloud { img: HTMLCanvasElement; shadow: HTMLCanvasElement; x: number; y: number; v: number; }

export class World {
  pal: Palette;
  private tile: HTMLCanvasElement;
  private isleImgs: HTMLCanvasElement[] = []; private isles: Isle[] = [];
  private cloudImgs: { img: HTMLCanvasElement; shadow: HTMLCanvasElement }[] = []; private clouds: Cloud[] = [];
  private off = 0; private nextIsle = 60; private nextCloud = 40; private seed = 3;

  constructor(p: Palette) {
    this.pal = p;
    this.tile = oceanTile(p);
    this.makeIsles();
    for (let i = 0; i < 4; i++) {
      const img = makeCloud(i * 31 + 7);
      this.cloudImgs.push({ img, shadow: tint(img, '#000000') });
    }
  }

  setPalette(p: Palette) {
    this.pal = p;
    this.tile = oceanTile(p);
    this.makeIsles();
    this.isles.forEach((s, i) => { s.img = this.isleImgs[i % this.isleImgs.length]; });
  }

  private makeIsles() {
    this.isleImgs = [];
    for (let i = 0; i < 5; i++) this.isleImgs.push(makeIsland(this.pal, this.seed++ * 17));
  }

  private addIsle(W: number, y: number) {
    const img = this.isleImgs[Math.floor(Math.random() * this.isleImgs.length)];
    this.isles.push({ img, x: Math.random() * (W + 40) - 20 - img.width / 2, y: y - img.height });
  }

  private addCloud(W: number, y: number, v: number) {
    const ci = this.cloudImgs[Math.floor(Math.random() * this.cloudImgs.length)];
    this.clouds.push({ ...ci, x: Math.random() * (W + 40) - 40, y: y - ci.img.height, v: v * (2.2 + Math.random() * 0.8) });
  }

  ensure(W: number, H: number) {
    if (!this.isles.length) { this.addIsle(W, H * 0.45); this.addIsle(W, H * 1.05); }
    if (!this.clouds.length) this.addCloud(W, H * 0.3, 26);
  }

  update(dt: number, W: number, H: number, v: number) {
    this.off = (this.off + v * dt) % 64;
    for (const s of this.isles) s.y += v * dt;
    this.isles = this.isles.filter(s => s.y < H + 4);
    this.nextIsle -= v * dt;
    if (this.nextIsle <= 0) { this.addIsle(W, 0); this.nextIsle = 70 + Math.random() * 150; }
    for (const c of this.clouds) c.y += c.v * dt;
    this.clouds = this.clouds.filter(c => c.y < H + 60);
    this.nextCloud -= v * dt;
    if (this.nextCloud <= 0) { this.addCloud(W, 0, v); this.nextCloud = 110 + Math.random() * 170; }
  }

  drawSea(c: CanvasRenderingContext2D, W: number, H: number, t: number) {
    const o = Math.floor(this.off);
    for (let y = o - 64; y < H; y += 64) for (let x = 0; x < W; x += 64) c.drawImage(this.tile, x, y);
    c.fillStyle = this.pal.crest;
    for (let i = 0; i < 30; i++) {
      const s = Math.floor(t * 2.2 + i * 0.37);
      if (hash(i, s, 5) > 0.6) continue;
      const gx = Math.floor(hash(i, s, 3) * W), gy = Math.floor((hash(i, s, 4) * H + this.off * 3) % H);
      c.fillRect(gx, gy, 2, 1);
    }
    for (const s of this.isles) c.drawImage(s.img, Math.round(s.x), Math.round(s.y));
    c.globalAlpha = 0.16;
    for (const cl of this.clouds) c.drawImage(cl.shadow, Math.round(cl.x + 30), Math.round(cl.y + 46));
    c.globalAlpha = 1;
    if (this.pal.tint) { c.fillStyle = this.pal.tint; c.fillRect(0, 0, W, H); }
  }

  drawClouds(c: CanvasRenderingContext2D) {
    c.globalAlpha = 0.55;
    for (const cl of this.clouds) c.drawImage(cl.img, Math.round(cl.x), Math.round(cl.y));
    c.globalAlpha = 1;
  }
}
